mapper.select:
SELECT s.workspace_uuid
FROM sessions s
JOIN workspaces w
ON w.uuid = s.workspace_uuid
AND w.organization_uuid = s.organization_uuid
WHERE s.uuid = #{params.SessionUUID}
AND s.organization_uuid = #{params.OrganizationUUID}
AND s.workspace_uuid = #{params.WorkspaceUUID}
AND s.status <> 'terminated'
AND s.archived_at IS NULL
AND s.deleted_at IS NULL
AND w.archived_at IS NULL
AND (
NOT #{params.HasCodeSession}
OR EXISTS (
SELECT 1
FROM code_sessions cs
WHERE cs.uuid = #{params.CodeSessionUUID}
AND cs.session_uuid = s.uuid
AND cs.organization_uuid = s.organization_uuid
AND cs.workspace_uuid = s.workspace_uuid
AND cs.status = 'active'
AND cs.deleted_at IS NULL
)
)
AND (
NOT #{params.HasCreatedByAPIKey}
OR EXISTS (
SELECT 1
FROM api_keys ak
WHERE ak.uuid = #{params.CreatedByAPIKeyUUID}
AND ak.workspace_uuid = w.uuid
)
)
LIMIT 1
FOR UPDATE OF s

SELECT

FROM filestore_filesystems
WHERE workspace_uuid = #{workspaceUUID}
AND (
external_id = #{filesystemExternalID}

    OR uuid = #{filesystemUUID}

)
AND deleted_at IS NULL
ORDER BY (external_id = #{filesystemExternalID}) DESC
LIMIT 1
FOR UPDATE

SELECT
FROM organizations o JOIN workspaces w ON w.organization_uuid = o.uuid JOIN users u ON u.organization_uuid = o.uuid AND u.deleted_at IS NULL JOIN filestore_filesystems fs ON fs.organization_uuid = o.uuid AND fs.workspace_uuid = w.uuid AND fs.deleted_at IS NULL JOIN sessions s ON s.uuid = fs.session_uuid AND s.organization_uuid = o.uuid AND s.workspace_uuid = w.uuid AND s.archived_at IS NULL AND s.deleted_at IS NULL AND s.status <> 'terminated' WHERE o.uuid = #{organizationUUID} AND u.uuid = #{accountUUID} AND w.uuid = #{workspaceUUID} AND w.external_id = #{workspaceTaggedID} AND w.external_id = #{resolvedWorkspaceTaggedID} AND ( fs.external_id = #{filesystemID}
OR fs.uuid = #{filesystemUUID}
) AND w.archived_at IS NULL ORDER BY (fs.external_id = #{filesystemID}) DESC LIMIT 1

SELECT

FROM filestore_filesystems
WHERE workspace_uuid = #{workspaceUUID}
AND (
external_id = #{filesystemID}

    OR uuid = #{filesystemUUID}

)
AND deleted_at IS NULL
ORDER BY (external_id = #{filesystemID}) DESC
LIMIT 1

SELECT

FROM filestore_filesystems
WHERE workspace_uuid = #{workspaceUUID}
AND session_uuid = (
SELECT uuid
FROM sessions
WHERE workspace_uuid = #{workspaceUUID}
AND external_id = #{sessionExternalID}
AND deleted_at IS NULL
)
AND deleted_at IS NULL
LIMIT 1

