WITH retired AS (
UPDATE filestore_filesystems fs
SET deleted_at = COALESCE(fs.deleted_at, #{retiredAt}),
updated_at = #{retiredAt}
WHERE fs.workspace_uuid = #{workspaceUUID}
AND fs.organization_uuid = #{organizationUUID}
AND fs.session_uuid = #{sessionUUID}
AND fs.deleted_at IS NULL
RETURNING fs.uuid
)
SELECT

FROM filestore_filesystems
WHERE uuid = (SELECT uuid FROM retired)

SELECT EXISTS (
SELECT 1
FROM filestore_filesystems fs
WHERE fs.workspace_uuid = #{workspaceUUID}
AND fs.external_id = #{filesystemExternalID}
)
